savedLevels.length-1;renderLevels();selectLevel(selected);closeModal();toast('Уровень сохранён!')};document.getElementById('editorTest').onclick=()=>{let name=document.getElementById('levelNameInput').value.trim()||'Мой уровень';if(!editorObjects.length){toast('Добавь препятствия перед тестом');return}let test={name,pattern:editorObjects.map(o=>o.x*6).sort((a,b)=>a-b),color:['#406e9c','#4d397f'],difficulty:'Тест',stars:1};closeModal();launchGame(test)}}
