let game=null,raf=0;
function launchGame(level){if(!level)return;closeModal();const portal=document.getElementById('portal');portal.innerHTML=`<section class="game-screen"><header class="game-top"><div class="game-ident"><button class="back-game" id="exitGame">←</button><div><div class="game-level-name">${level.name}</div><div class="game-level-sub">NEON DASH · NORMAL MODE</div></div></div><div class="game-top-right"><span id="progressText">0%</span><div class="progress-wrap"><div class="progress-fill" id="progressFill"></div></div><button class="icon-btn" id="pauseGame" aria-label="Пауза">Ⅱ</button></div></header><div class="game-stage"><div class="game-frame"><canvas class="game-canvas" id="gameCanvas"></canvas><div class="game-hud">✦ &nbsp;${level.name.toUpperCase()}</div><div class="game-overlay" id="gameOverlay"><div class="overlay-card"><h2 id="overlayTitle">На старт?</h2><p id="overlayText">Тапни, нажми пробел или кнопку ниже</p><button class="primary" id="overlayAction">▶ &nbsp;Начать</button></div></div></div></div><footer class="game-bottom"><span class="control-hint"><span class="keycap">SPACE</span> или клик</span><button class="tap-button" id="jumpButton" aria-label="Прыгнуть">↑</button><span class="control-hint">Тапни для прыжка</span></footer></section>`;const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');const screen=document.querySelector('.game-screen'),overlay=document.getElementById('gameOverlay');let state='ready',last=0,world=0,playerY=0,vy=0,rotation=0,particles=[],flash=0;const obstacles=(level.pattern||levels[0].pattern).map((x,i)=>({x,type:level.objects?.[i]?.type||'spike'}));const finish=(obstacles.length?obstacles[obstacles.length-1].x:4800)+470;game={};function resize(){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*d));canvas.height=Math.max(1,Math.round(r.height*d));ctx.setTransform(d,0,0,d,0,0);draw()}window.addEventListener('resize',resize);const clean=()=>{window.removeEventListener('resize',resize);cancelAnimationFrame(raf);game=null;portal.innerHTML=''};document.getElementById('exitGame').onclick=clean;function begin(){if(state==='ready'){state='running';overlay.classList.add('hidden');last=performance.now()}else if(state==='dead'||state==='won'){world=0;playerY=vy=rotation=0;particles=[];state='running';overlay.classList.add('hidden');document.getElementById('overlayAction').textContent='▶  Начать';last=performance.now()}else if(state==='running'){if(playerY>=-1){vy=-540;burst(80,0)}}}
function pause(){if(state==='running'){state='paused';document.getElementById('overlayTitle').textContent='Пауза';document.getElementById('overlayText').textContent='Отдохни секунду и продолжай';document.getElementById('overlayAction').textContent='▶  Продолжить';overlay.classList.remove('hidden')}else if(state==='paused'){state='running';overlay.classList.add('hidden');last=performance.now()}}
document.getElementById('pauseGame').onclick=pause;document.getElementById('overlayAction').onclick=()=>{if(state==='paused')pause();else begin()};document.getElementById('jumpButton').addEventListener('pointerdown',e=>{e.preventDefault();begin()});canvas.addEventListener('pointerdown',e=>{e.preventDefault();begin()});const keydown=e=>{if(e.code==='Space'||e.code==='ArrowUp'){e.preventDefault();begin()}if(e.code==='Escape')pause()};window.addEventListener('keydown',keydown);const oldClean=clean;function draw(){if(!ctx)return;let w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;let ground=h*.79,px=w*.22,size=Math.max(23,h*.09);let bg=ctx.createLinearGradient(0,0,0,h);bg.addColorStop(0,level.color?.[1]||'#1b2451');bg.addColorStop(.72,level.color?.[0]||'#162143');bg.addColorStop(1,'#11172d');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle='#c2d6ff';ctx.lineWidth=1;let offset=(world*.35)%42;for(let x=-42-offset;x<w+42;x+=42){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,ground);ctx.stroke()}for(let y=22;y<ground;y+=34){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.restore();for(let i=0;i<32;i++){let x=((i*137-world*.08)%(w+40)+w+40)%(w+40),y=(i*67%Math.max(1,ground-20))+10;ctx.globalAlpha=.22+(i%3)*.1;ctx.fillStyle=i%2?'#8beeff':'#ffe6a0';ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;ctx.fillStyle='#192647';ctx.fillRect(0,ground,w,h-ground);ctx.fillStyle=level.accent||'#54e6d9';ctx.shadowColor=level.accent||'#54e6d9';ctx.shadowBlur=14;ctx.fillRect(0,ground,w,3);ctx.shadowBlur=0;for(let x=-((world*.8)%32);x<w+30;x+=32){ctx.fillStyle='#2c3b5f';ctx.fillRect(x,ground+12,18,3);ctx.fillRect(x+8,ground+26,15,3)}for(const o of obstacles){let sx=px+o.x-world;if(sx<-50||sx>w+50)continue;ctx.save();ctx.shadowColor='#ff69ae';ctx.shadowBlur=16;if(o.type==='block'){ctx.fillStyle='#a18cff';ctx.fillRect(sx-size/2,ground-size,size,size);ctx.strokeStyle='#eee2ff';ctx.lineWidth=2;ctx.strokeRect(sx-size/2,ground-size,size,size)}else if(o.type==='orb'){ctx.beginPath();ctx.arc(sx,ground-size*1.65,size*.34,0,Math.PI*2);ctx.fillStyle='#ffdc78';ctx.fill();ctx.strokeStyle='#fff1b7';ctx.lineWidth=3;ctx.stroke()}else{ctx.beginPath();ctx.moveTo(sx-size*.62,ground);ctx.lineTo(sx,ground-size*1.14);ctx.lineTo(sx+size*.62,ground);ctx.closePath();let sg=ctx.createLinearGradient(sx,ground-size,sx,ground);sg.addColorStop(0,'#ffb0ca');sg.addColorStop(1,'#ff558f');ctx.fillStyle=sg;ctx.fill();ctx.strokeStyle='#ffe1ef';ctx.lineWidth=2;ctx.stroke()}ctx.restore()}particles.forEach(p=>{ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)});ctx.globalAlpha=1;let y=ground-size-playerY;ctx.save();ctx.translate(px,y+size/2);ctx.rotate(rotation);ctx.shadowColor='#82ffe9';ctx.shadowBlur=19;let cg=ctx.createLinearGradient(-size/2,-size/2,size/2,size/2);cg.addColorStop(0,'#efff9f');cg.addColorStop(1,'#4adacb');ctx.fillStyle=cg;ctx.strokeStyle='#f0ffda';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-size/2,-size/2,size,size,4);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='#294451';ctx.lineWidth=3;ctx.strokeRect(-size*.22,-size*.18,size*.44,size*.44);ctx.restore();if(flash>0){ctx.fillStyle=`rgba(255,255,255,${flash*.25})`;ctx.fillRect(0,0,w,h)}}
function burst(x,y){for(let i=0;i<8;i++)particles.push({x,y,vx:(Math.random()-.5)*140,vy:-Math.random()*160,size:2+Math.random()*4,life:.8,color:['#b8ff88','#50f1e0','#ffd47b'][i%3]})}function die(){if(state!=='running')return;state='dead';burst(canvas.clientWidth*.22,canvas.clientHeight*.65);if(navigator.vibrate)navigator.vibrate(45);document.getElementById('overlayTitle').textContent='Почти!';document.getElementById('overlayText').textContent=`Рекорд попытки: ${Math.floor(world/finish*100)}% · ещё раз?`;document.getElementById('overlayAction').textContent='↻  Повторить';overlay.classList.remove('hidden')}
function frame(now){if(!game)return;let dt=Math.min(.035,(now-last)/1000||0);last=now;if(state==='running'){world+=310*dt;vy+=1500*dt;playerY-=vy*dt;if(playerY<0){playerY=0;vy=0}if(playerY>0)rotation+=dt*6;else rotation=Math.round(rotation/(Math.PI/2))*Math.PI/2;for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);let progress=Math.min(100,world/finish*100);document.getElementById('progressText').textContent=Math.floor(progress)+'%';document.getElementById('progressFill').style.width=progress+'%';let px=canvas.clientWidth*.22,size=Math.max(23,canvas.clientHeight*.09);for(const o of obstacles){let sx=px+o.x-world;if(Math.abs(sx-px)<size*.75&&playerY<size*.6&&o.type!=='orb'){die();break}}if(world>=finish){state='won';document.getElementById('overlayTitle').textContent='Уровень пройден!';document.getElementById('overlayText').textContent='Идеальный ритм. Ты справился!';document.getElementById('overlayAction').textContent='↻  Сыграть ещё';let p=Math.max(100,Math.floor(progress));best[level.name]=100;localStorage.setItem('neondash-best',JSON.stringify(best));document.getElementById('progressText').textContent='100%';document.getElementById('progressFill').style.width='100%';if(levels.includes(level)){renderLevels();selectLevel(levels.indexOf(level))}else{best[level.name]=100;localStorage.setItem('neondash-best',JSON.stringify(best))}overlay.classList.remove('hidden')}}draw();raf=requestAnimationFrame(frame)}resize();raf=requestAnimationFrame(frame);
}
</script>
</body>
